'use client';

import Icon from '@/components/Icon';
import { shortDate } from '@/lib/budget';

export const TABS = [
  { id: 'overview', label: 'Overview', short: 'Home', icon: 'layout-dashboard', color: 'var(--mint)' },
  { id: 'log', label: 'Log gastos', short: 'Log', icon: 'pen-line', color: 'var(--lime)' },
  { id: 'manage', label: 'Manage gastos', short: 'Manage', icon: 'list-checks', color: 'var(--pink)' },
  { id: 'calculator', label: 'Calculator', short: 'Calc', icon: 'calculator', color: 'var(--peach)' },
  { id: 'advisor', label: 'AI Advisor', short: 'Advisor', icon: 'bot', color: 'var(--sky)' },
] as const;

export type TabId = (typeof TABS)[number]['id'];

interface SidebarProps {
  tab: TabId;
  onTab: (t: TabId) => void;
  start: string;
  end: string;
  remaining: number;
  statusColor: string;
  onSettings: () => void;
}

export default function Sidebar({ tab, onTab, start, end, remaining, statusColor, onSettings }: SidebarProps) {
  return (
    <>
      {/* Desktop / tablet rail */}
      <aside className="side hidden md:flex" aria-label="Main navigation">
        <div className="flex items-center gap-3 px-2">
          <div className="w-10 h-10 rounded-[14px] bg-[var(--lime)] text-[#0E0E10] grid place-items-center font-display font-extrabold text-xl -rotate-6 shrink-0">₱</div>
          <div className="min-w-0">
            <p className="font-display font-extrabold text-[17px] leading-none tracking-tight">Estudyante Balanse</p>
            <p className="text-xs text-muted mt-1">Budget mo, kontrolado mo.</p>
          </div>
        </div>

        <nav className="mt-8 flex flex-col gap-1">
          {TABS.map(t => (
            <button
              key={t.id}
              type="button"
              className="nav-item"
              aria-current={tab === t.id ? 'page' : undefined}
              style={{ '--c': t.color } as React.CSSProperties}
              onClick={() => onTab(t.id)}
            >
              <span className="nav-ic"><Icon name={t.icon} /></span>
              <span>{t.label}</span>
            </button>
          ))}
        </nav>

        <div className="mt-auto side-card">
          <p className="eyebrow">{remaining < 0 ? 'Over by' : 'Natitira'}</p>
          <p className="font-display font-extrabold text-2xl tracking-[-.04em] tnum mt-1 flex items-center gap-2">
            <span className="w-2 h-2 rounded-full shrink-0" style={{ background: statusColor }} />
            ₱{Math.round(Math.abs(remaining)).toLocaleString('en-PH')}
          </p>
          <button type="button" className="pill sm mt-3 w-full justify-center" onClick={onSettings}>
            <Icon name="calendar" className="w-3.5 h-3.5 text-muted" />
            <span className="tnum">{shortDate(start)} – {shortDate(end)}</span>
          </button>
        </div>
      </aside>

      {/* Mobile bottom bar */}
      <nav className="tabbar md:hidden" aria-label="Main navigation">
        {TABS.map(t => (
          <button
            key={t.id}
            type="button"
            aria-current={tab === t.id ? 'page' : undefined}
            style={{ '--c': t.color } as React.CSSProperties}
            onClick={() => onTab(t.id)}
          >
            <span className="nav-ic"><Icon name={t.icon} /></span>
            <span>{t.short}</span>
          </button>
        ))}
      </nav>
    </>
  );
}
